	if isLocalDelivery {
		shippingCost = 0
	}

	order := &models.Order{
		AddressID:       addressID,
		UserID:          user.ID,
		PaymentIntentID: paymentIntentID,
		Notes:           notesValue,
		TaxRate:         models.CurrentTaxRate,
		ShippingCost:    shippingCost,
	}
