// ClientSecret is the resolver for the clientSecret field.
func (r *queryResolver) ClientSecret(ctx context.Context, totalCost float64, clientSecret *string) (*string, error) {
	user, err := requireUser(ctx)
	if err != nil {
		return nil, err
	}

	var cart []models.UserProduct
	if err := r.DB.Where("user_id = ?", user.ID).Preload("Product").Find(&cart).Error; err != nil {
		return nil, err
	}

	var description strings.Builder
	subTotal := 0
	for _, item := range cart {
		fmt.Fprintf(&description, "%s - $%.2f x%d \n", item.Product.Title, float64(item.Product.Price)/100, item.Count)
		subTotal += item.Product.Price * item.Count
	}
	fmt.Fprintf(&description, "Shipping - $%.2f \n", float64(models.CurrentShippingCost)/100)
	tax := math.Floor(models.CurrentTaxRate * float64(subTotal))
	fmt.Fprintf(&description, "Tax - $%.2f \n", tax/100)

	sc := stripe.NewClient(os.Getenv("STRIPE_SECRET_KEY"))

	var paymentIntent *stripe.PaymentIntent
	if clientSecret != nil && *clientSecret != "" {
		paymentIntentID := strings.Split(*clientSecret, "_secret")[0]
		paymentIntent, err = sc.V1PaymentIntents.Retrieve(ctx, paymentIntentID, nil)
		if err != nil {
			return nil, err
		}
		if paymentIntent.Status != stripe.PaymentIntentStatusSucceeded {
			paymentIntent, err = sc.V1PaymentIntents.Update(ctx, paymentIntentID, &stripe.PaymentIntentUpdateParams{
				Amount:      stripe.Int64(int64(totalCost)),
				Description: stripe.String(description.String()),
			})
			if err != nil {
				return nil, err
			}
		}
	} else {
		paymentIntent, err = sc.V1PaymentIntents.Create(ctx, &stripe.PaymentIntentCreateParams{
			Amount:      stripe.Int64(int64(totalCost)),
			Description: stripe.String(description.String()),
			Currency:    stripe.String("usd"),
			AutomaticPaymentMethods: &stripe.PaymentIntentCreateAutomaticPaymentMethodsParams{
				Enabled: stripe.Bool(true),
			},
		})
		if err != nil {
			return nil, err
		}
	}

	result := paymentIntent.ClientSecret
	return &result, nil
}

