func (r *queryResolver) PaymentSucceeded(ctx context.Context, clientSecret string) (bool, error) {
	if _, err := requireUser(ctx); err != nil {
		return false, err
	}
	return r.checkPaymentSucceeded(ctx, clientSecret)
}

